const comparison=[['Current sequence','Prioritize critical order','Prioritize + resequence'][0],['Current sequence','Prioritize critical order','Prioritize + resequence'][1],['Current sequence','Prioritize critical order','Prioritize + resequence'][2]].map((label,i)=>{const m=plan.options[i].metrics;return [label,`${m.priorityOnTime}/${m.priorityDemand}`,String(m.kitsOnTime),`${m.productiveHours} h`,cash(m.modeledCost)];});
const actions=[['Before release','Planner + warehouse','Reserve 40 finished modules and 140 released sensors for the priority order.'],['Hours 0–8','MES scheduler','Build 140 priority modules, then 20 standard modules. Park the remaining 160 standard units.'],['Hours 8–26','Shift supervisor + quality','Approve the 2-hour, $600 setup. Build 160 independent service kits.'],['Throughout','Account owner + procurement','Agree the late standard commitment. Keep the supplier restriction and receipt review open.']];
const slides=[
 {kind:'cover',title:'Markov',subtitle:'Local operations agent',body:'A disruption changes the plan. Markov connects the evidence, compares feasible responses, and prepares the next decision.',foot:'Cornell NVIDIA × Dell Hackathon',notes:'Markov helps an operations team respond when a supplier event invalidates the production plan. The agent keeps watching, gathers the relevant business context, and prepares a mitigation for the people who own the next action. The example will show allocation and line resequencing while the supplier restriction stays unresolved.',sources:[]},
 {kind:'chain',title:'A supplier event changes the production plan',subtitle:'A rare-earth export licence suspension reaches final assembly through three downstream tiers.',foot:'One direct supplier. Five downstream suppliers. Saved network risk score: 0.961.',notes:'The worked event is evt_004 at Altiplano Rare Earth in Antofagasta, Chile. The six suppliers and their edges come from the repository’s seed records and deterministic propagation result. Risk is an exposure-prioritization score, not a probability or a financial-loss estimate. The operational question is which available stock and independent work can protect customer commitments.',sources:['code','ops']},
 {kind:'market',title:'Defense is one demanding customer segment',subtitle:'A broad industrial ecosystem depends on specialist firms several tiers below the prime.',foot:'These counts describe different populations. They are market context, not a paying-customer TAM.',notes:'Defense offers a demanding use case because supplier relationships, qualifications, and program schedules can be sensitive. The 300,000 ecosystem estimate covers defense and private-sector suppliers. Brookings discusses incomplete DoD visibility into more than 12,000 small and midsize subcontractors. The consolidation figure refers to aerospace and defense primes, from 51 in 1993 to 5 in 2000, reported by DoD in 2022. The original 100,000-plus figure appears in a 2021 industrial-capabilities graphic reproduced in the 2024 strategy; its scope is not directly comparable with the broad 300,000 estimate.',sources:['dib','brookings','competition']},
 {kind:'studies',title:'Disruptions carry a substantial operating cost',subtitle:'Downtime and supply-chain studies measure different parts of the same operational problem.',foot:'Separate studies, years, samples, and definitions. These figures are not added together.',notes:'Siemens estimates annual unplanned-downtime losses of $1.4 trillion across the world’s 500 largest companies, equal to 11 percent of revenue, up from 8 percent in 2019. Interos 2023 surveyed 750 leaders and reported an average $82 million annual loss from supply-chain disruptions. Interos 2021 surveyed 900 decision makers at organizations with more than $1 billion revenue and reported $184 million average annual disruption-related lost revenue. These are separate populations and are not a basis for Markov customer savings forecasts.',sources:['siemens','interos23','interos21']},
 {kind:'downtime',title:'Downtime makes the decision window costly',subtitle:'Large automotive plants illustrate the urgency of a workable response.',foot:'Siemens, The True Cost of Downtime, 2024. Industry context, not a Markov savings estimate.',notes:'Siemens reports $2.3 million per hour of unplanned downtime for large automotive plants. The 2024 report also describes an increase in average recovery time from 49 minutes in the 2019 study to 81 minutes in the 2023 study. It cites lost maintenance skills, supply delays, and harder remaining failures. We do not claim that Markov removes all or any measured share of those restoration minutes. Our own worked example uses explicit inventory, orders, rates, and fee assumptions instead.',sources:['siemens']},
 {kind:'local',title:'Operational context stays under company control',subtitle:'Local inference keeps sensitive supplier and production records close to the teams that own them.',foot:'Security, access, and deployment controls must match each customer’s requirements.',notes:'Local architecture can reduce third-party exposure of supplier networks, stock positions, customer commitments, and process constraints. Defense is a useful case, but manufacturers, semiconductor suppliers, energy operators, and pharmaceutical operations can have similar needs. DFARS and ITAR do not impose a blanket cloud ban. Qualifying cloud configurations can be permitted, and running locally alone does not establish compliance. This product direction centers on company-controlled data and local inference.',sources:['dfars','itar']},
 {kind:'workflow',title:'The agent connects disruption to mitigation',subtitle:'Business records turn supplier exposure into an executable decision for review.',foot:'The agent keeps the incident open and reassesses when inventory, timing, quality, or receipts change.',notes:'The complete workflow starts with a disruption, joins supplier and operational context, compares feasible operating choices, and prepares a mitigation with owners and timing. In the worked example, warehouse stock, the MES queue and approved kit BOM, customer deadlines and fees, and quality restrictions determine the decision. The comparison uses transparent calculations. A language model can explain and draft the result while human owners approve physical and commercial actions.',sources:['code','ops']},
 {kind:'stack',title:'A local stack with clear responsibilities',subtitle:'Inference, deterministic calculations, monitoring, and approval routing have distinct roles.',foot:'GB10 is the target on-premises platform. Ports shown are local service defaults.',notes:'The target platform is NVIDIA GB10. Qwen serves as the language model through Ollama. MongoDB stores supplier and event records. FastAPI exposes the analysis and monitor. React provides the workspace. Deterministic code determines supplier exposure and compares the worked operational options. The independent monitor scans over time. The narration layer can use the optional OpenClaw gateway, direct Ollama, or template wording. Component configuration and integration determine the deployment behavior.',sources:['code','ops']},
 {kind:'gateway',title:'OpenClaw turns context into a reviewable response',subtitle:'Local reasoning connects business constraints to proposed actions.',foot:'Reassess as inventory, schedules, quality, and receipts change.',notes:'OpenClaw has two roles in the code: an optional model harness through an OpenAI-compatible chat endpoint and optional dispatch of a review packet through tools/invoke. The wording path tries the enabled gateway, falls back to direct Ollama, and then to deterministic templates. A disabled or unavailable review channel records an undelivered outcome. This is distinct from automatically executing a supplier order, inventory reservation, or production change. Such physical and commercial decisions require accountable approval.',sources:['code']},
 {kind:'comparison',title:'A feasible plan reduces modeled cost by $21,000',subtitle:'40-hour worked example at Cascade Final Assembly',foot:'160 standard modules remain late. The supplier restriction stays open.',notes:`The default comparison uses 160 released sensor arrays, 40 finished modules, and 40 quality-held sensors that stay excluded. A single line builds 20 modules/hour. Priority demand is 180 modules due by hour 16 at $150 per late unit. Standard demand is 180 due by hour 40 at $25 per late unit. The kit order is 160 due by hour 40 at $10 per late unit. Independent kits use 10/hour after a two-hour, $600 changeover and require released stock, an approved BOM, and qualified crew. Current sequence costs $25,600; priority allocation costs $5,600; priority plus resequencing costs $4,600, comprising $4,000 late fees and $600 setup. The $21,000 difference is modeled fees plus setup, not measured revenue savings. Productive time rises from 8 to 24 hours. 180 priority modules and 160 kits finish on time; 160 standard modules remain late. Alternate qualification requires 120 scheduled hours and no dated receipt is committed, so waiting for an alternate is excluded.`,sources:['ops']},
 {kind:'actions',title:'The proposal has owners, quantities, and timing',subtitle:'The recommended allocation and release sequence stays reviewable before anyone acts.',foot:'Applicable to manufacturing, semiconductors, energy, pharmaceuticals, and defense supply chains.',notes:'The planner and warehouse lead first approve 40 finished modules and 140 sensors for priority work. The line produces 140 priority modules during hours zero through seven and 20 standard modules during hours seven through eight. At hour eight, the scheduler parks the incomplete standard job rather than blocking independent work. Quality and the supervisor approve a two-hour changeover, then 160 kits run during hours ten through twenty-six. The account owner reviews the remaining 160 late standard modules and procurement keeps monitoring the restriction and actual receipts. The general product serves operational workflows with dependencies, constrained alternatives, and sensitive data.',sources:['ops']},
];

Object.assign(SOURCES,{
 siemens22:['Siemens, The True Cost of Downtime, 2022, p. 6. Automotive downtime about $2M/hour, rounded down to $33,000/minute.','https://assets.new.siemens.com/siemens/assets/api/uuid%3A3d606495-dbe0-43e4-80b1-d04e27ada920/dics-b10153-00-7600truecostofdowntime2022-144.pdf'],
 sheer:['Sheer Logistics, December 4, 2024, reporting Interos 2023: average four major disruptions per year and approximately $22M per incident.','https://sheerlogistics.com/blog/supply-chain-disruption/'],
 ndia:['NDIA, Vital Signs 2022. Defense vendor base about 69,000 in 2016 to 55,000 in 2020.','https://www.ndia.org/-/media/sites/ndia/policy/vital-signs/2022/vital-signs_2022---web.pdf']
});
Object.assign(slides[0],{subtitle:'A local agent for plans that cannot wait',body:'Defense subcontractors carry the most fragile supply chains in the country and the strictest limits on where their data may go. Markov watches on hardware they already own, finds what changed, and prepares the next decision. No supplier name, quantity, or schedule leaves the building.',foot:'Cornell NVIDIA × Dell Hackathon · NVIDIA GB10 · Local inference · Zero cloud LLM calls'});
slides[1]={kind:'definition',title:'A disruption can invalidate the plan',subtitle:'A plan-invalidating event makes the current plan impossible to execute as written.',foot:'A changed schedule, an impossible delivery, or an exposed commitment requires a replacement decision.',sources:['ops'],notes:'The original definition is retained: any event that makes the plan currently being executed impossible to execute as written, and therefore obliges someone to decide quickly what replaces it. The demo uses the export licence suspension affecting Altiplano Rare Earth. That external cause remains unresolved while Markov identifies workable allocation and production changes.'};
Object.assign(slides[2],{title:'The supplier that stops the program may be invisible',subtitle:'A hundred thousand companies—and incomplete visibility into the specialists programs depend on.',foot:'The vendor base fell from about 69,000 firms in 2016 to 55,000 in 2020. Each remaining dependency matters.',sources:['dib','brookings','competition','ndia']});
Object.assign(slides[3],{title:'What a year of unexecutable plans costs',subtitle:'Downtime consumes 11% of revenue at the world’s 500 largest companies, up from 8% in 2019.',foot:'Separate studies and surveyed populations; the figures are not added together.',sources:['siemens','interos23','interos21','sheer']});
Object.assign(slides[4],{title:'$33,000 a minute. The clock starts before the decision.',subtitle:'Cost accrued using a large automotive plant’s downtime rate, since this slide appeared.',foot:'$33,000/min rounds down the 2022 $2M/hour estimate. The 2024 study reports $2.3M/hour.',sources:['siemens22','siemens'],notes:slides[4].notes+' The live counter uses the 2022 automotive downtime rate rounded down to $33,000/min, accruing continuously at $550 per second from elapsed time. It illustrates elapsed cost at that rate, not measured loss at a particular business. HTML resets to zero each time slide 5 is entered and continues indefinitely. The PowerPoint embeds a 300.1-second animated GIF at ten frames per second, repeating in desktop Slide Show, plus editable rate text. PowerPoint web may show only the first frame; use the HTML deck for the live counter.'});
Object.assign(slides[5],{title:'Every prompt naming a supplier stays on the customer’s hardware',subtitle:'For defense programs the supplier graph is operating context worth protecting: local inference keeps relationships, stock, schedules, and program commitments on the box.',foot:'Access controls, contractual duties, and export rules still apply. Local execution supports those controls.',notes:slides[5].notes+' ITAR access restrictions concern foreign persons and controlled technical data, not only server geography. Cloud use can be permitted under qualifying controls. We do not assert a blanket ban or an automatic compliance certification.'});
Object.assign(slides[6],{title:'Watch unattended. Trace exposure. Draft a response.',subtitle:'The model writes the explanation. Recorded dependencies determine who is affected.',foot:'One licence suspension. Six exposed firms. Three downstream tiers. Network risk score: 0.961.',notes:slides[6].notes+' The backend agent README records a 0.57-second fallback response in an earlier integration run with the model down; it is not a universal latency claim. Current verification includes more than 200 automated backend checks. Cloud LLM calls are not required by the local architecture.'});
const mitigationSlides=slides.splice(9,2);
slides.push({kind:'savings',title:'Shorten the distance from the event to the decision',subtitle:'An illustrative large-plant scenario: reducing decision delay while the root cause is repaired.',foot:'Assumed time reduction, not measured Markov savings. The rate is for a large automotive plant.',sources:['siemens22','siemens'],notes:'The original savings arithmetic is preserved with explicit scope. At the rounded 2022 large-automotive-plant downtime rate of $33,000 per minute, ten avoided minutes imply $330,000 and three imply $99,000. Ten minutes is roughly 12 percent of an 81-minute restoration window, not a verified avoidable share. Twelve such events at ten minutes each imply $3.96 million at the same rate. These assumptions are not extrapolated across small subcontractors or presented as national savings. Defense programs also care about schedule and readiness, which are not reduced to a fabricated dollar total.'},...mitigationSlides,{kind:'beyond',title:'Three conditions. One product across industries.',subtitle:'Defense makes the constraints clear. The architecture also serves broader corporate operations.',foot:'Insert an event, let the agent find it, and review the response with the people responsible.',sources:['code','ops'],notes:'The three original conditions are dependency graphs, events that invalidate plans, and sensitive data. Target use cases include pharmaceuticals and validated supply, semiconductors and allocation, energy assets and long-lead equipment, hospital consumables and sensitive data, and banking vendor concentration. Local execution is useful wherever companies prefer to retain control of their operational context.'});
// Inserted by kind, deliberately: the patches above address slides by index,
// and the splice/push below reorders them, so an index here would rot.
slides.splice(slides.findIndex(s=>s.kind==='local')+1,0,{kind:'compliance',title:'What the rules ask, and what running locally changes',subtitle:'Local deployment is not a compliance certificate. It removes the part of the problem that is hardest to prove.',foot:'Neither DFARS nor ITAR bans cloud outright. Both place the burden of proof on the contractor.',notes:'This slide is deliberately precise because the audience will know the regulations. DFARS 252.204-7012 permits an external cloud service that meets FedRAMP Moderate equivalency, so cloud is not prohibited; it is conditional and must be evidenced. CMMC requires demonstrating the NIST SP 800-171 controls across every system touching CUI, which means scope drives cost. The ITAR exclusion at 22 CFR 120.54 is conditional on end-to-end encryption and on keys being inaccessible to foreign persons. Running on premises does not by itself establish compliance; it shrinks the boundary that has to be assessed and removes the third-party conditions from the argument. Do not claim the cloud is illegal.',sources:['dfars','nist','cmmc','itar']});
slides.splice(slides.findIndex(s=>s.kind==='compliance')+1,0,{kind:'sovereign',title:'For some of this work there is no cloud option to compare against',subtitle:'Air-gapped areas, deployed sites, and small subcontractors are not choosing local over cloud. Local is the only thing that runs.',foot:'DFARS 252.204-7012 requires reporting a cyber incident within 72 hours, and paragraph (m) flows that duty to subcontractors unaltered.',notes:'Three arguments here, in increasing order of how hard they are to answer. First, closed areas and disconnected sites have no egress path at all, so a cloud agent is not slower, it is absent; a single box that runs offline is the only deployable form. Second, an accredited enclave is a real annual cost, which the large primes can carry and many of the twelve thousand small subcontractors cannot; the hardware they already own is affordable. Third, a provider-side incident involving your CUI becomes your seventy-two hour report to DoD, and 7012 paragraph (m) pushes that obligation down the chain unaltered, so every tier inherits it. Removing the third party removes that failure mode rather than managing it. Do not claim cloud is banned; claim the burden and the exposure are removed.',sources:['dfars','brookings']});
const esc=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const mark='<span class="mark" aria-hidden="true"><i></i><i></i><i></i></span>';
const table=(heads,rows,cls='')=>`<div class="table-wrap"><table class="${cls}"><thead><tr>${heads.map(v=>`<th>${esc(v)}</th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr${cls==='options'&&i===2?' class="recommended"':''}>${row.map((v,j)=>`<${j?'td':'th'}${j?'':' scope="row"'}>${esc(v)}</${j?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const flow=(items,cls='')=>`<div class="flow ${cls}">${items.map(([a,b])=>`<div><strong>${esc(a)}</strong><span>${esc(b)}</span></div>`).join('')}</div>`;
const stats=(items,cost=false)=>`<div class="stat-grid ${cost?'cost-stats':''}">${items.map(([value,label,source])=>`<div class="stat"><strong>${esc(value)}</strong><p>${esc(label)}</p><small>${esc(source)}</small></div>`).join('')}</div>`;
const columns=items=>`<div class="prose-cols">${items.map(([title,body])=>`<div><h3>${esc(title)}</h3><p>${esc(body)}</p></div>`).join('')}</div>`;
const chainHtml=()=>`<div class="chain compact-chain"><div><span>Direct supplier</span><b>Altiplano Rare Earth</b><small>Neodymium magnet billet</small></div><div><span>Tier 1</span><b>Shenzhen Micro Sensors</b><b>Great Lakes Stamping</b></div><div><span>Tier 2</span><b>Delta Assembly Works</b><b>Ardennes Wiring Systems</b></div><div><span>Final assembly</span><b>Cascade Final Assembly</b><small>Finished powertrain module</small></div></div>`;
function htmlContent(s){switch(s.kind){
 case 'cover':return `<div class="cover-word">${mark}<h1>Markov</h1></div><h2 class="cover-subtitle">${s.subtitle}</h2><p class="cover-copy">${s.body}</p>${flow([['Watch','Continuously'],['Trace','Dependencies'],['Plan','Feasible responses'],['Review','Accountable owner']],'cover-flow')}`;
 case 'definition':return `<div class="definition"><h3>Plan-invalidating event</h3><p>Any event that makes the plan you are currently executing impossible to execute as written—and obliges someone to decide, quickly, what replaces it.</p></div>${columns([['The event','A rare-earth export licence is suspended indefinitely.'],['What it invalidates','The build sequence for assemblies that require the magnet billet.'],['Who decides','A named person, inside hours, with authority to commit to the replacement.']])}`;
 case 'market':return stats(market)+`<p class="takeaway">You cannot manage exposure through a supplier you cannot identify.</p>`;
 case 'studies':return stats(studies,true)+columns(consequence);
 case 'downtime':return `<div class="waste-clock"><div class="clock-label">Accruing at $33,000 per minute</div><div class="accrued" id="accrued" role="timer" aria-label="Estimated cost accrued since entering this slide">$0</div><div class="clock-bottom"><strong>$550 per second</strong><span>Cost accrued since this slide appeared</span></div></div><div class="clock-context"><p><strong>$2.3M / hour</strong><span>Large automotive plants · Siemens 2024</span></p><p><strong>49 → 81 minutes</strong><span>Average recovery · 2019 and 2023 studies</span></p></div><p class="clock-explain">A stopped station can affect labor, assembly, and outbound shipping. A workable decision should not wait for the full repair.</p>`;
 case 'local':return columns([['Access is about people, not regions','Controlled technical data restricts who may see it, not only where the server sits. A US region alone does not answer a person-based requirement.'],['Aggregation changes sensitivity','A part number, a supplier, a quantity, a date. Individually routine; compiled, they describe a program, its tempo, and its single points of failure.'],['Nothing to disclose, nothing to retain','A cloud call transmits the whole prompt: supplier names, stock positions, schedules, program references. Locally there is no vendor log, retention window, or subprocessor list to reason about.']])+`<div class="definition compact-definition"><h3>Company-controlled operations</h3><p>The full dependency graph and the context needed to choose a response stay close to the team that owns the decision. Cloud inference is not required at any point in the workflow.</p></div>`;
 case 'sovereign':return columns([['No egress path exists','A closed area or a disconnected site has nowhere to send a prompt. A cloud agent is not slower there; it is absent. One box that runs offline is the only deployable form.'],['An enclave is a cost, not a checkbox','A primes-grade accredited environment is an annual expense. Many of the 12,000 small subcontractors cannot carry it. The hardware on their floor they already own.'],['A provider incident becomes your report','A third-party compromise touching your CUI is still your 72-hour report to DoD, and the clause flows that duty to every subcontractor. No third party, no inherited exposure.']])+`<div class="payoff"><strong>Removing the third party removes the failure mode</strong><span>rather than adding controls to manage it</span></div>`;
 case 'compliance':return table(['Requirement','What it asks of the contractor','What local deployment changes'],compliance,'actions')+`<p class="takeaway">Local does not prove compliance. It shrinks the boundary that has to be proven.</p>`;
 case 'workflow':return flow([['Watch','New events'],['Trace','Recorded dependencies'],['Draft','Local reasoning'],['Review','Responsible person']])+chainHtml()+`<div class="proof-line"><span><b>0.57s</b> recorded fallback run</span><span><b>3</b> downstream tiers</span><span><b>200+</b> automated checks</span><span><b>0</b> cloud LLM calls</span></div>`;
 case 'stack':return table(['Component','Responsibility','Location'],stack,'stack');
 case 'gateway':return `<div class="gateway"><div><h3>Context and reasoning</h3><p>Synthesize supplier updates, inventory, schedules, order priorities, and quality rules.</p><p>Explain why the selected option fits resources and deadlines.</p><p><code>POST /v1/chat/completions</code></p><p>The gateway resolves which model answers, so <code>ollama/qwen3.6:35b</code> is configuration rather than a hard-wired call.</p></div><div><h3>Review and routing</h3><p>Package quantified impact, accountable owners, and timed actions for the responsible person.</p><p>Keep decisions and delivery status in the activity trail.</p><p><code>POST /tools/invoke</code></p><p>The review packet reaches the responsible person in the channel they already use, dispatched from the box.</p></div></div>${flow([['Gather context','Relevant business records'],['Compare options','Resources and deadlines'],['Prepare response','Impact, owners, timing']])}`;
 case 'savings':return table(['Assumption / input','Illustrative result'],savings,'savings')+`<div class="payoff"><strong>12 events × $330,000 = $3.96M</strong><span>At the same large-plant rate and assumed 10-minute reduction</span></div><p class="model-note">No national savings extrapolation. On defense programs, the same avoided delay also protects schedule and readiness.</p>`;
 case 'comparison':return table(['Option','Priority on time','Kits on time','Productive time','Fees + setup'],comparison,'options')+`<div class="payoff"><strong>${cash(plan.recommended.metrics.costReduction)} reduced</strong><span>+${plan.recommended.metrics.productiveHoursRecovered} productive hours</span><span>${plan.recommended.metrics.priorityOnTime} priority modules + ${plan.recommended.metrics.kitsOnTime} kits on time</span></div><p class="model-note">40 finished modules, 160 released sensors, and an approved independent kit job make this plan feasible. Modeled fees + setup.</p>`;
 case 'actions':return table(['Timing','Accountable owner','Proposed action'],actions,'actions')+`<p class="takeaway">An actionable plan for the next shift, with the remaining exception still visible.</p>`;
 case 'beyond':return columns(conditions)+`<div class="industry-list"><span>Pharmaceuticals · validated supply</span><span>Semiconductors · allocation</span><span>Energy · long-lead assets</span><span>Hospital systems · consumables</span><span>Banking · vendor concentration</span></div><p class="takeaway">One local architecture for sensitive dependencies and time-critical decisions.</p>`;
}}

